import fs from 'node:fs';
function replaceOnce(text,from,to,label){const count=text.split(from).length-1;if(count!==1)throw new Error(`${label}: expected exactly one match; found ${count}.`);return text.replace(from,to);}
let schema=fs.readFileSync('workflow-schema.js','utf8');
schema=replaceOnce(schema,"  'CHAIN':Object.freeze({","  'PRODUCT':Object.freeze({GENERATED_ARTIFACT_INVENTORY:Object.freeze({valueType:'STRING_ARRAY',enumValues:Object.freeze([]),nullable:false,normalizerKey:null,closedProperties:null})}),\n  'CHAIN':Object.freeze({",'type product artifact inventory as filename array');
fs.writeFileSync('workflow-schema.js',schema);
let engine=fs.readFileSync('workflow-engine.js','utf8');
const oldGate="    case 21:{requireAccepted();const products=recordsForCurrentScope(project,'products'),product=products.at(-1),productId=recordId(product,'products'),artifacts=recordsForCurrentScope(project,'artifacts').filter(a=>productId&&String(a.scope?.productId||'')===productId);if(products.length!==1)reasons.push('Exactly one current product execution identity is required.');if(!recordsForCurrentScope(project,'baselines').length)reasons.push('An approved production baseline is required.');if(!artifacts.length)reasons.push('Actual finished-product bytes must be persisted and hashed before Stage 21 can complete.');break;}";
const newGate="    case 21:{requireAccepted();const products=recordsForCurrentScope(project,'products'),product=products.at(-1),productId=recordId(product,'products'),artifacts=recordsForCurrentScope(project,'artifacts').filter(a=>productId&&String(a.scope?.productId||'')===productId),inventory=recordValue(product,'GENERATED_ARTIFACT_INVENTORY');if(products.length!==1)reasons.push('Exactly one current product execution identity is required.');if(!recordsForCurrentScope(project,'baselines').length)reasons.push('An approved production baseline is required.');if(!Array.isArray(inventory)||!inventory.length)reasons.push('The product execution must declare the exact expected output filenames.');else{const expected=inventory.map(value=>String(value||'').trim()),expectedSet=new Set(expected),actual=artifacts.map(a=>String(recordValue(a,'FILENAME')||'').trim()),actualSet=new Set(actual);if(expected.some(name=>!name)||expectedSet.size!==expected.length)reasons.push('Expected product output filenames must be non-empty and unique.');if(actual.some(name=>!name)||actualSet.size!==actual.length)reasons.push('Current product artifact filenames must be non-empty and unique.');const missing=[...expectedSet].filter(name=>!actualSet.has(name)),unexpected=[...actualSet].filter(name=>!expectedSet.has(name));if(missing.length)reasons.push('Finished-product bytes are missing for declared output filename(s): '+missing.join(', ')+'.');if(unexpected.length)reasons.push('Unexpected finished-product artifact filename(s) exist outside the declared product inventory: '+unexpected.join(', ')+'.');}if(artifacts.some(a=>upper(recordValue(a,'AVAILABILITY'))!=='BYTES_PERSISTED_AND_VERIFIED'||!/^[a-f0-9]{64}$/i.test(String(recordValue(a,'SHA256')||''))||!Number.isInteger(Number(recordValue(a,'BYTE_SIZE')))||Number(recordValue(a,'BYTE_SIZE'))<0))reasons.push('Every finished-product artifact must have persisted, verified bytes with exact size and SHA-256.');break;}";
engine=replaceOnce(engine,oldGate,newGate,'reconcile Stage 21 declared inventory to verified product bytes');
fs.writeFileSync('workflow-engine.js',engine);
let full=fs.readFileSync('verify-full-cycle.mjs','utf8');
full=replaceOnce(full,"GENERATED_ARTIFACT_INVENTORY:'ARTIFACT-PRODUCT'","GENERATED_ARTIFACT_INVENTORY:['product.bin']",'use filename inventory in Stage 21 fixture');
full=replaceOnce(full,"engine.registerArtifactBytes(p,{stage:21,artifactId:'ARTIFACT-PRODUCT',filename:'product.bin',mediaType:'application/octet-stream',byteSize:productBytes.byteLength,sha256:productSha,lineage:{productId}});complete(21);","engine.registerArtifactBytes(p,{stage:21,artifactId:'ARTIFACT-PRODUCT',filename:'product.bin',mediaType:'application/octet-stream',byteSize:productBytes.byteLength,sha256:productSha,lineage:{productId}});{const missing=engine.clone(p),mp=engine.recordsForCurrentScope(missing,'products').at(-1);mp.fields.GENERATED_ARTIFACT_INVENTORY=['product.bin','missing.bin'];mp.GENERATED_ARTIFACT_INVENTORY=['product.bin','missing.bin'];assert(!engine.gate(21,missing).complete,'Stage 21 accepted a declared output with no verified bytes.');const extra=engine.clone(p);engine.registerArtifactBytes(extra,{stage:21,artifactId:'ARTIFACT-EXTRA',filename:'extra.bin',mediaType:'application/octet-stream',byteSize:1,sha256:hash.sha256Text('x'),lineage:{productId}});assert(!engine.gate(21,extra).complete,'Stage 21 accepted an undeclared extra product artifact.');const duplicate=engine.clone(p);engine.registerArtifactBytes(duplicate,{stage:21,artifactId:'ARTIFACT-DUPLICATE',filename:'product.bin',mediaType:'application/octet-stream',byteSize:1,sha256:hash.sha256Text('x'),lineage:{productId}});assert(!engine.gate(21,duplicate).complete,'Stage 21 accepted duplicate product filenames that cannot be reconciled one-to-one.');}complete(21);",'add Stage 21 inventory regressions');
fs.writeFileSync('verify-full-cycle.mjs',full);
let workbook=fs.readFileSync('workbook.js','utf8');
workbook=replaceOnce(workbook,"'Fresh production context used only approved baseline materials','Every requested output exists with controlled identity','Every output hash is recorded','No uncontrolled edit occurred'","'Fresh production context used only approved baseline materials','Every requested output exists with controlled identity; GENERATED_ARTIFACT_INVENTORY lists the exact expected output filenames','Every output hash is recorded','No uncontrolled edit occurred'",'clarify Stage 21 inventory prompt semantics');
fs.writeFileSync('workbook.js',workbook);
console.log(JSON.stringify({patched:['workflow-schema.js','workflow-engine.js','verify-full-cycle.mjs','workbook.js']},null,2));